size_t fn_20(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {
  if (out_cap < len) {
    return -1;
  }

  uint8_t p[8];
  for (size_t i = 0; i < 8; i++) {
    p[i] = i;
  }

  for (size_t i = 7; i > 0; i--) {
    size_t j = arg % (i + 1);
    arg /= (i + 1);
    uint8_t t = p[i];
    p[i] = p[j];
    p[j] = t;
  }

  for (size_t i = 0; i + 8 <= len; i += 8) {
    for (size_t j = 0; j < 8; j++) {
      out[i + j] = in[i + p[j]];
    }
  }

  for (size_t i = len; i < len; i++) {
    out[i] = in[i];
  }

  return len;
}

